function harness(body,initial){
 let slots=[],effects=[],cursor=0,pending=[],dirty=false,tree,props={label:'Probe',value:0,...initial},calls=[],blurCalls=0;
 const useState=initial=>{const i=cursor++;if(!(i in slots))slots[i]=typeof initial==='function'?initial():initial;return [slots[i],v=>{const next=typeof v==='function'?v(slots[i]):v;if(!Object.is(slots[i],next)){slots[i]=next;dirty=true;}}];};
 const useEffect=(fn,deps)=>{const i=cursor++,old=effects[i];if(!old||deps.some((v,k)=>!Object.is(v,old[k]))){effects[i]=deps;pending.push(fn);}};
 const js=transformSync('field.tsx',body+'\nglobalThis.Render=NumberField;',{jsx:{runtime:'classic'}}).code;
 const context={useState,useEffect,React:{createElement:(type,props,...children)=>({type,props:{...props,children}})}};
 vm.runInNewContext(js,context);
 function render(){let count=0;do{dirty=false;cursor=0;pending=[];tree=context.Render({...props,onChange:value=>{calls.push(value);if(typeof props.accept==='function'){props={...props,value:props.accept(value)};dirty=true;}}});for(const effect of pending)effect();assert(++count<20,'render settled');}while(dirty);}
 function input(){return tree.props.children.find(x=>x?.type==='input').props;}
 render();
 return {type(value){input().onChange({target:{value}});render();},commit(){input().onBlur();render();},enter(){input().onKeyDown({key:'Enter',currentTarget:{blur(){blurCalls++;input().onBlur();}}});render();},external(value){props={...props,value};render();},value:()=>input().value,calls:()=>[...calls],blurCalls:()=>blurCalls};
}

